//! Integer conversions of the SoundFont units: cents to pitch ratios,
//! timecents to frames, centibels to linear gain, and the pan law.
//!
//! The tables are generated by `build.rs` on the build host; here they are
//! only indexed and interpolated, in integer arithmetic.

include!(concat!(env!("OUT_DIR"), "/tables.rs"));

/// A sample rate in Hz as the exact fraction `numerator / denominator`.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct Rate {
    /// Numerator in Hz.
    pub numerator: u32,
    /// Denominator, at least 1.
    pub denominator: u32,
}

impl Rate {
    /// A whole number of Hz.
    #[must_use]
    pub const fn hz(hz: u32) -> Self {
        Self {
            numerator: hz,
            denominator: 1,
        }
    }
}

/// The audio driver's output rate: the 100 MHz PWM clock over a range of
/// 2268, 44 091.71 Hz (audio design, D4).
pub const OUTPUT_RATE: Rate = Rate {
    numerator: 100_000_000,
    denominator: 2268,
};

/// Attenuation at and past which a voice is silent, in centibels (96 dB).
pub const SILENT_CENTIBELS: u32 = 960;

/// `value * 2^(cents / 1200)`, rounded, for `value` below 2^32.
#[must_use]
#[expect(
    clippy::cast_possible_truncation,
    reason = "callers keep the result within u64 by their ranges"
)]
pub fn scale_by_cents(value: u64, cents: i32) -> u64 {
    let octave = cents.div_euclid(1200);
    let within = usize::try_from(cents.rem_euclid(1200)).unwrap_or(0);
    // value < 2^32 and the ratio < 2^31: the product fits 63 bits.
    let scaled = u128::from(value) * u128::from(CENT_RATIOS_Q30[within]);
    let shift = 30 - octave;
    let result = if shift >= 0 {
        let shift = shift.unsigned_abs().min(127);
        (scaled + ((1_u128 << shift) >> 1)) >> shift
    } else {
        scaled << shift.unsigned_abs().min(64)
    };
    result.min(u128::from(u64::MAX)) as u64
}

/// The sample position step in 32.32 fixed point of a sample recorded at
/// `sample_rate` Hz played `cents` above its root, rendered at `output`.
#[must_use]
pub fn phase_step(sample_rate: u32, cents: i32, output: Rate) -> u64 {
    // sample_rate / output in 32.32, then scaled by the pitch ratio.
    let ratio = ((u128::from(sample_rate) * u128::from(output.denominator)) << 32)
        / u128::from(output.numerator.max(1));
    let ratio = u64::try_from(ratio).unwrap_or(u64::MAX);
    // Keep the multiplicand below 2^32 by splitting off the whole part.
    let whole = ratio >> 32;
    let fraction = ratio & 0xffff_ffff;
    scale_by_cents(whole, cents)
        .saturating_mul(1 << 32)
        .saturating_add(scale_by_cents(fraction, cents))
        // Beyond 2^38 (64 times the sample rate) nothing sensible is left.
        .min(1 << 38)
}

/// The number of frames at `rate` that `timecents` last:
/// `2^(timecents / 1200)` seconds, clamped to the SoundFont's -12 000
/// (1 ms) to 8 000 (101.6 s).
#[must_use]
pub fn timecents_frames(timecents: i32, rate: Rate) -> u32 {
    let timecents = timecents.clamp(-12_000, 8_000);
    // rate in 16.16 times the ratio.
    let rate_q16 = (u64::from(rate.numerator) << 16) / u64::from(rate.denominator.max(1));
    let frames_q16 = scale_by_cents(rate_q16, timecents);
    u32::try_from((frames_q16 + (1 << 15)) >> 16).unwrap_or(u32::MAX)
}

/// Linear gain in Q16 of an attenuation in Q16 centibels: the table
/// interpolated between whole centibels, 0 at [`SILENT_CENTIBELS`] and past.
#[must_use]
pub fn attenuation_gain(centibels_q16: u32) -> u32 {
    let whole = usize::try_from(centibels_q16 >> 16).unwrap_or(usize::MAX);
    let fraction = centibels_q16 & 0xffff;
    match (
        ATTENUATION_GAINS_Q16.get(whole),
        ATTENUATION_GAINS_Q16.get(whole + 1),
    ) {
        (Some(&here), Some(&next)) => here - (((here - next) * fraction) >> 16),
        _ => 0,
    }
}

/// The attenuation in Q16 centibels of a linear gain in Q16 (the inverse of
/// [`attenuation_gain`], interpolated between whole centibels).
#[must_use]
pub fn gain_attenuation(gain_q16: u32) -> u32 {
    // The table falls with the index: find the first entry at or below the gain.
    let index = ATTENUATION_GAINS_Q16.partition_point(|&gain| gain > gain_q16);
    if index == 0 {
        return 0;
    }
    let Some(&below) = ATTENUATION_GAINS_Q16.get(index) else {
        return SILENT_CENTIBELS << 16;
    };
    let above = ATTENUATION_GAINS_Q16[index - 1];
    let fraction = ((above - gain_q16) << 16) / (above - below).max(1);
    ((u32::try_from(index).unwrap_or(SILENT_CENTIBELS) - 1) << 16) + fraction
}

/// The attenuation in centibels of the concave curve at `value` (0 to 127):
/// velocity, channel volume and expression.
#[must_use]
pub fn concave_centibels(value: u8) -> u32 {
    u32::from(CONCAVE_CENTIBELS[usize::from(value.min(127))])
}

/// Left and right gains in Q15 of SoundFont pan `pan` (-500 hard left to 500
/// hard right).
#[must_use]
pub fn pan_gains(pan: i32) -> (u32, u32) {
    let position = usize::try_from(pan.clamp(-500, 500) + 500).unwrap_or(500);
    (
        u32::from(PAN_GAINS_Q15[position]),
        u32::from(PAN_GAINS_Q15[1000 - position]),
    )
}
